create or replace function public.scheduled_achievement_queue(run_date date default current_date)returns table(manufacturer_id uuid,manufacturer_name text,manufacturer_slug text,logo_url text,primary_color text,recipient text,notification_type text,content_title text,message text,dedupe_key text)language sql security definer set search_path='' as $f$
with certificate_rows as(select m.id,m.name,m.slug,m.logo_url,m.primary_color,u.email,'certificate'::text kind,c.title,c.content_type||' completed' message,'certificate:'||c.id key from public.certificates c join public.manufacturers m on m.id=c.manufacturer_id join public.manufacturer_notification_settings s on s.manufacturer_id=m.id and s.certificate_enabled join auth.users u on u.id=c.user_id where c.issued_at>=s.updated_at and not exists(select 1 from public.notification_deliveries d where d.dedupe_key='certificate:'||c.id)),dealer_status as(select p.manufacturer_id,p.id program_id,p.name program_name,a.company_id,co.name company_name,s.summary_email,count(cm.user_id)filter(where not exists(select 1 from public.certification_requirements r where r.program_id=p.id and not(case when r.content_type='quiz' then exists(select 1 from public.quiz_attempts qa join public.quizzes q on q.id=qa.quiz_id where qa.company_id=a.company_id and qa.user_id=cm.user_id and qa.quiz_id=r.content_id and qa.status='completed' and qa.score>=q.passing_score)else(select count(*)from public.course_block_progress cp where cp.company_id=a.company_id and cp.user_id=cm.user_id and cp.course_id=r.content_id)>=(select count(*)from public.course_blocks b join public.course_modules mo on mo.id=b.module_id where mo.course_id=r.content_id)and(select count(*)from public.course_blocks b join public.course_modules mo on mo.id=b.module_id where mo.course_id=r.content_id)>0 end)))qualified,p.minimum_certified_learners from public.company_certification_assignments a join public.certification_programs p on p.id=a.program_id join public.companies co on co.id=a.company_id join public.manufacturer_notification_settings s on s.manufacturer_id=p.manufacturer_id and s.certified_dealer_enabled and s.summary_email is not null left join public.company_members cm on cm.company_id=a.company_id and cm.status='active' group by p.manufacturer_id,p.id,p.name,a.company_id,co.name,s.summary_email,p.minimum_certified_learners),dealer_rows as(select m.id,m.name,m.slug,m.logo_url,m.primary_color,d.summary_email,'certified_dealer',d.company_name,d.program_name||' requirements completed','dealer:'||d.program_id||':'||d.company_id key from dealer_status d join public.manufacturers m on m.id=d.manufacturer_id where d.qualified>=d.minimum_certified_learners and not exists(select 1 from public.notification_deliveries n where n.dedupe_key='dealer:'||d.program_id||':'||d.company_id)),summary_rows as(select m.id,m.name,m.slug,m.logo_url,m.primary_color,s.summary_email,'weekly_summary',m.name||' weekly training summary',format('%s active retailer locations and %s learner certificates issued.',(select count(*)from public.manufacturer_companies mc where mc.manufacturer_id=m.id and mc.status='active'),(select count(*)from public.certificates c where c.manufacturer_id=m.id)),'summary:'||m.id||':'||to_char(run_date,'IYYY-IW') key from public.manufacturers m join public.manufacturer_notification_settings s on s.manufacturer_id=m.id and s.weekly_summary_enabled and s.summary_email is not null where extract(isodow from run_date)=1 and not exists(select 1 from public.notification_deliveries d where d.dedupe_key='summary:'||m.id||':'||to_char(run_date,'IYYY-IW')))
select * from certificate_rows union all select * from dealer_rows union all select * from summary_rows;$f$;
revoke all on function public.scheduled_achievement_queue(date)from public,anon,authenticated;grant execute on function public.scheduled_achievement_queue(date)to service_role;
